<script setup lang="ts">
import { reactive, ref } from 'vue'
import { couponsApi, type Coupon, type CouponInput } from '../api/coupons'
const rows = ref<Coupon[]>([]), page = ref(1), pages = ref(0), keyword = ref(''), status = ref(''), loading = ref(false), busy = ref(false), message = ref(''), editing = ref(false), id = ref<string | null>(null), claimed = ref(false)
const blank = (): CouponInput => ({ name: '', amount: 10, minimumAmount: 100, startTime: '', endTime: '', quantity: 100, status: 'active' })
const form = reactive<CouponInput>(blank())
async function load() { loading.value = true; try { const r = await couponsApi.adminList(page.value, keyword.value, status.value); rows.value = r.list; pages.value = r.pages } catch(e) { message.value = (e as Error).message } finally { loading.value = false } }
async function edit(c?: Coupon) { message.value = ''; busy.value = true; try { const data = c ? await couponsApi.detail(c.id) : null; Object.assign(form, data ? { ...data, startTime: data.startTime.replace(' ', 'T'), endTime: data.endTime.replace(' ', 'T') } : blank()); id.value = data?.id || null; claimed.value = Number(data?.claimedQuantity || 0) > 0; editing.value = true } catch(e) { message.value = (e as Error).message } finally { busy.value = false } }
async function save() { if (busy.value) return; busy.value = true; message.value = ''; try { await couponsApi.save(id.value, { name: form.name, amount: Number(form.amount), minimumAmount: Number(form.minimumAmount), quantity: Number(form.quantity), startTime: form.startTime.length === 16 ? form.startTime + ':00' : form.startTime, endTime: form.endTime.length === 16 ? form.endTime + ':00' : form.endTime, status: form.status === 'expired' ? 'inactive' : form.status }); editing.value = false; await load(); message.value = '保存成功' } catch(e) { message.value = (e as Error).message } finally { busy.value = false } }
async function remove(c: Coupon) { if (!window.confirm(`删除“${c.name}”？已领取的优惠券仍保留。`)) return; busy.value = true; try { await couponsApi.remove(c.id); if(rows.value.length === 1 && page.value > 1) page.value--; await load() } catch(e) { message.value = (e as Error).message } finally { busy.value = false } }
void load()
</script>
<template><div class="admin-page"><h1>优惠券管理</h1><p>维护发行数量、领取状态及有效期。已有用户领取后，面额、门槛和有效期不可修改。</p>
  <form class="actions" @submit.prevent="page = 1; load()"><input v-model="keyword" placeholder="优惠券名称" maxlength="100" /><select v-model="status"><option value="">全部状态</option><option value="active">启用</option><option value="inactive">停用</option><option value="expired">已过期</option></select><button :disabled="loading">查询</button><button type="button" :disabled="busy" @click="edit()">新增优惠券</button></form>
  <p v-if="message" role="status">{{ message }}</p><p v-if="loading">正在加载…</p>
  <form v-if="editing" class="panel editor" @submit.prevent="save"><h2>{{ id ? '编辑优惠券' : '新增优惠券' }}</h2>
    <label>名称<input v-model="form.name" required maxlength="100" /></label><label>面额（元）<input v-model.number="form.amount" :disabled="claimed" required type="number" min="0.01" max="99999999.99" step="0.01" /></label><label>使用门槛（元）<input v-model.number="form.minimumAmount" :disabled="claimed" required type="number" min="0" max="99999999.99" step="0.01" /></label><label>开始时间<input v-model="form.startTime" :disabled="claimed" required type="datetime-local" step="1" /></label><label>结束时间<input v-model="form.endTime" :disabled="claimed" required type="datetime-local" step="1" /></label><label>发行总量<input v-model.number="form.quantity" required type="number" min="0" max="2147483647" step="1" /></label><label>状态<select v-model="form.status"><option value="active">启用</option><option value="inactive">停用</option><option v-if="form.status === 'expired'" value="expired">已过期</option></select></label><div><button :disabled="busy">保存</button><button type="button" :disabled="busy" @click="editing = false">取消</button></div>
  </form>
  <div class="table-wrap"><table><thead><tr><th>名称</th><th>面额 / 门槛</th><th>有效期</th><th>发行 / 已领 / 剩余</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td>{{ c.name }}</td><td>¥{{ c.amount }} / ¥{{ c.minimumAmount }}</td><td>{{ c.startTime }} — {{ c.endTime }}</td><td>{{ c.quantity }} / {{ c.claimedQuantity }} / {{ c.remainingQuantity }}</td><td>{{ ({ active: '启用', inactive: '停用', expired: '已过期' } as Record<string,string>)[c.status] || c.status }}</td><td><button :disabled="busy" @click="edit(c)">编辑</button><button :disabled="busy" @click="remove(c)">删除</button></td></tr></tbody></table><p v-if="!loading && !rows.length">暂无优惠券</p></div>
  <div class="actions"><button :disabled="loading || page <= 1" @click="page--; load()">上一页</button><span>{{ page }} / {{ Math.max(1, pages) }}</span><button :disabled="loading || page >= pages" @click="page++; load()">下一页</button></div>
</div></template>
<style scoped>.actions{display:flex;gap:12px;margin:20px 0;flex-wrap:wrap}.editor{display:grid;gap:14px;margin-bottom:24px}.editor label{display:grid;gap:6px}input,select,button{padding:9px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-bottom:1px solid #ddd}</style>
